import {Link} from '@primer/react'
import type {CopilotMcpRegistryPolicy} from '../types'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import {ShieldLockIcon} from '@primer/octicons-react'
import {ActionMenuButton} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'

type McpRegistryAccessProps = {
  options: ActionMenuButtonOption[]
  selected: ActionMenuButtonOption | undefined
  onSelect: (option: ActionMenuButtonOption) => void
  loading: boolean
  policy: CopilotMcpRegistryPolicy
  inputDisabled: boolean
}

export default function McpRegistryAccess({
  options,
  selected,
  onSelect,
  loading,
  policy,
  inputDisabled,
}: McpRegistryAccessProps) {
  const disabled = !policy.configurable

  if (!policy.visible) {
    return null
  }

  return (
    <>
      <div data-testid={`cfb-policies-${policy.manages}-feature`} className="ml-3" style={{maxWidth: 750}}>
        <PreviewFeatureHeading title={policy.displayname} beta={policy.preview!} />
        {policy.description}
        <br />
        {policy.helpurl && policy.helptext && (
          <Link href={policy.helpurl} inline>
            {policy.helptext}
          </Link>
        )}
      </div>
      {disabled ? (
        <span data-testid={`cfb-policies-${policy.manages}-feature-locked`}>
          <ShieldLockIcon /> {selected?.title ?? 'Disabled'}
        </span>
      ) : (
        <ActionMenuButton
          title={selected?.title}
          options={options}
          onSelect={onSelect}
          disabled={inputDisabled}
          loading={loading}
          data-testid={`cfb-policies-${policy.manages}-control`}
        />
      )}
    </>
  )
}

try{ McpRegistryAccess.displayName ||= 'McpRegistryAccess' } catch {}