export function isValidUrl(value: string) {
  let url
  try {
    // this can be any arbitrary URL, we don't want to append window.location.origin like the eslint rule wants
    // eslint-disable-next-line no-restricted-syntax
    url = new URL(value)
  } catch {
    return false
  }

  if (!['http:', 'https:'].includes(url.protocol)) {
    return false
  }

  if (url.username || url.password) {
    return false
  }

  if (!url.host) {
    return false
  }

  return true
}
