import {isFeatureEnabled} from '@github-ui/feature-flags'

function FeaturesForDataRetention({showCopilotInTheCLI}: {showCopilotInTheCLI: boolean | null}) {
  const features = []
  if (showCopilotInTheCLI) features.push('Copilot in the CLI')
  features.push('Copilot in GitHub.com')
  features.push('Copilot Chat in GitHub Mobile')
  let message = ''
  if (features.length === 1) {
    message = `Enabling ${features[0]} will collect additional data and updated`
  } else if (features.length === 2) {
    message = `Enabling ${features[0]} and ${features[1]} will collect additional data and updated`
  } else if (features.length === 3) {
    message = `Enabling ${features[0]}, ${features[1]} and ${features[2]} will collect additional data and updated`
  }

  return (
    <>
      {message && (
        <>
          {message}{' '}
          <Link
            href="https://github.com/customer-terms/github-copilot-product-specific-terms"
            className="Link--inTextBlock"
            inline
          >
            Product Terms
          </Link>{' '}
          apply.{' '}
        </>
      )}
    </>
  )
}

// List of models in the order they should be displayed.
// TODO: delete after rollout
const model_order = [
  'a_chat',
  'a_f',
  'afos',
  'daisy',
  'al',
  'aofo',
  'g_chat',
  'g_tf',
  'gtff',
  'o1',
  'o3',
  'o_ff',
  'o_fm',
  'o_f',
  'o_t',
  'ofo',
  'obmb',
  'ofct',
  'obmw',
  'grok_code',
  'm_ironman',
  'm_spiderman',
  'm_thor',
] satisfies Array<keyof CopilotForBusinessModelsPayload>

export function ModelsPageEntrypointLegacy() {
  const payload = useRoutePayload<CopilotForBusinessModelsPayload>()
  return <ModelsPageWrapper payload={payload} />
}

export function ModelsPageEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessModelsRoute, 'mainQuery')
  return <ModelsPageWrapper payload={payload} />
}

function ModelsPageWrapper({payload}: {payload: CopilotForBusinessModelsPayload}) {
  return (
    <>
      <PageHeading name="Copilot models" />
      <DefaultOrCustomModelSelector org={payload.org_name} />
      <ModelsPage payload={payload} />
    </>
  )
}

function ModelsPage({payload}: {payload: CopilotForBusinessModelsPayload}) {
  const {
    enterprise_name,
    enterprise_slug,
    copilot_plan: plan,
    docsUrls,
    models,
    model_policies,
    ...modelsPayload
  } = payload
  const showCopilotInTheCLI = !isFeatureEnabled('copilot_agent_cli_public_preview')
  const modelPolicies = model_policies || []

  // TODO: just use `models` once rollout is complete
  const filteredModels = useMemo(() => {
    if (models) {
      return Object.values(models)
    }
    return model_order
      .map(model => {
        const data = modelsPayload[model]
        if (!data) return null
        return data.visible ? data : null
      })
      .filter(model => model !== null)
  }, [modelsPayload, models])

  return (
    <>
      <div {...testIdProps('models-page-intro')} className={clsx(styles.topBox, 'mb-3')}>
        <span className={clsx(styles.muted)}>
          Manage policies and grant access to Copilot models for all members with access.
          <br />
          Note that users from other organizations may gain access if permitted by their administrators.
        </span>
        {enterprise_name && enterprise_slug && (
          <span className={clsx(styles.muted, 'mr-2')} {...testIdProps('cfb-managed-organization-enterprise')}>
            <ShieldLockIcon /> Managed by{' '}
            <Link inline href={`/enterprises/${enterprise_slug}`}>
              {enterprise_name}
            </Link>
          </span>
        )}
      </div>
      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
        }}
      >
        <BoxSection>
          {[...filteredModels, ...modelPolicies].map(model => (
            <GeneralPolicy payload={payload} key={model.manages} policy={model} />
          ))}
        </BoxSection>
        <Text as="p" sx={{color: 'fg.muted'}} data-testid="cb-policies-footnotes">
          {' '}
          {plan !== 'enterprise' && <FeaturesForDataRetention showCopilotInTheCLI={showCopilotInTheCLI} />}
          If preview features are enabled, you agree to{' '}
          <Link href="https://docs.github.com/site-policy/github-terms/github-copilot-pre-release-license-terms" inline>
            pre-release terms
          </Link>
          . For more information about the data your organization receives regarding your use of GitHub Copilot, please
          review{' '}
          <Link href={docsUrls.generalPrivacyStatement} inline>
            GitHub&apos;s Privacy Statement
          </Link>
          .
        </Text>
      </Box>
    </>
  )
}

try{ FeaturesForDataRetention.displayName ||= 'FeaturesForDataRetention' } catch {}
try{ ModelsPageEntrypointLegacy.displayName ||= 'ModelsPageEntrypointLegacy' } catch {}
try{ ModelsPageEntrypoint.displayName ||= 'ModelsPageEntrypoint' } catch {}
