function UserFeedbackPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const org = useEnsureOrgName(payload)
  const data = payload.copilot_user_feedback_opt_in

  const {addToast} = useToastContext()
  const useCopilotSettingsMutation = useCreateMutator(seatManagementEndpoint, {org})

  const [updateOption, loading] = useCopilotSettingsMutation<Record<string, string>, {success: boolean}>({
    resource: 'policies',
    method: 'PUT',
  })

  const onChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const isFeedbackEnabled = event.target.checked
      updateOption({
        payload: {[data.manages]: isFeedbackEnabled ? 'enabled' : 'disabled'},
        onError(e) {
          let message = 'Something went wrong. Please try again later.'
          if (e && typeof e === 'object' && 'message' in e) message = String(e.message)

          // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
          addToast({message, role: 'alert', type: 'error'})
        },
        onComplete(res) {
          if (res && res.success) {
            // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
            addToast({
              message: `User feedback is now ${isFeedbackEnabled ? 'enabled' : 'disabled'}`,
              role: 'alert',
              type: 'success',
            })
          }
        },
      })
    },
    [updateOption, addToast, data.manages],
  )

  const disabled = !data.configurable
  if (!data.visible) return null

  return (
    <Box as="form" sx={{mt: 2, pl: 3}}>
      <FormControl disabled={disabled || loading}>
        <Checkbox onChange={onChange} defaultChecked={data.enabled} data-testid="cfb-policies-feedback-checkbox" />
        <FormControl.Label style={{display: 'flex', alignItems: 'center', marginBottom: '8px'}}>
          Opt in to free text user feedback collection
        </FormControl.Label>
        <FormControl.Caption style={{fontSize: 'var(--base-size-14)'}}>
          <p>
            Enables user feedback collection on Copilot features in github.com. This feedback may include sensitive
            information.
          </p>
        </FormControl.Caption>
      </FormControl>
    </Box>
  )
}

function CopilotCLIPolicy({
  payload,
  showCopilotInTheCLI,
  showBeta,
}: {
  payload: CopilotForBusinessPoliciesPayload
  showCopilotInTheCLI: boolean
  showBeta: boolean
}) {
  const data = payload.cli

  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: data.options,
    controls: data.manages,
  })

  const disabled = !data.configurable

  const featureHeading = showCopilotInTheCLI ? 'Copilot in the CLI' : 'Copilot CLI'
  const featureDescription = showCopilotInTheCLI
    ? 'GitHub Copilot assistance in the terminal'
    : 'GitHub Copilot CLI as an assistant in the terminal'
  const featureDocUrl = showCopilotInTheCLI
    ? 'https://docs.github.com/copilot/github-copilot-in-the-cli/using-github-copilot-in-the-cli'
    : 'https://gh.io/copilot-cli'

  return (
    <>
      <div data-testid="cfb-policies-cli-feature">
        <PreviewFeatureHeading title={featureHeading} beta={showBeta} />
        If enabled, members of this organization will get{' '}
        <Link href={featureDocUrl} inline>
          {featureDescription}
        </Link>
        {showCopilotInTheCLI ? (
          <>
            {' and '}
            <br />
            <Link href="https://learn.microsoft.com/en-us/windows/terminal/terminal-chat" inline>
              {'Windows Terminal Chat'}
            </Link>
          </>
        ) : null}
        .
      </div>
      {disabled ? (
        <span data-testid="cfb-policies-cli-feature-locked">
          <ShieldLockIcon /> {selected?.title ?? 'Disabled'}
        </span>
      ) : (
        <ActionMenuButton
          title={selected?.title ?? 'Disabled'}
          options={options}
          onSelect={onSelect}
          disabled={disabled}
          loading={loading}
          data-testid="cfb-policies-cli-feature-button"
        />
      )}
    </>
  )
}

