function CcrDirectOrgBillingPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const data = payload.ccr_direct_org_billing
  const org = useEnsureOrgName(payload)
  const {addToast} = useToastContext()
  const useCopilotSettingsMutation = useCreateMutator(seatManagementEndpoint, {org})

  const [updateOption, loading] = useCopilotSettingsMutation<Record<string, string>, {success: boolean}>({
    resource: 'policies',
    method: 'PUT',
  })

  const onChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (!data) return
      const isEnabled = event.target.checked

      updateOption({
        payload: {[data.manages]: isEnabled ? 'enabled' : 'disabled'},
        onError(e) {
          let message = 'Something went wrong. Please try again later.'
          if (e && typeof e === 'object' && 'message' in e) message = String(e.message)

          // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
          addToast({message, role: 'alert', type: 'error'})
        },
        onComplete(res) {
          if (res && res.success) {
            // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
            addToast({
              message: `Copilot code review direct billing is now ${isEnabled ? 'enabled' : 'disabled'}`,
              role: 'alert',
              type: 'success',
            })
          }
        },
      })
    },
    [updateOption, addToast, data],
  )

  if (!data || !data.visible) return null

  const disabled = !data.configurable

  // Show the PRU warning when:
  // - CCR Direct Org Billing is not configurable (checkbox disabled)
  // - PRU is not enabled
  // - The general CCR policy IS configurable (meaning business allows org control)
  // This indicates PRU is the only blocker preventing configuration
  const ccrConfigurable = payload.code_review?.configurable ?? false
  const showPruWarning = disabled && !data.pru_enabled && ccrConfigurable

  return (
    <Box sx={{mt: 3, pl: 3}}>
      <FormControl disabled={disabled || loading}>
        <Checkbox onChange={onChange} defaultChecked={data.enabled} data-testid="ccr-direct-org-billing-checkbox" />
        <FormControl.Label style={{display: 'flex', alignItems: 'center', marginBottom: '8px'}}>
          Allow members without a Copilot license to use Copilot code review in github.com
        </FormControl.Label>
        <FormControl.Caption style={{fontSize: 'var(--base-size-14)'}}>
          <Text>
            All members in this organization can use Copilot code review on their pull requests in github.com. If
            configured,{' '}
            <Link
              href="https://docs.github.com/en/copilot/using-github-copilot/code-review/configuring-automatic-code-review-by-copilot"
              inline
            >
              Automatic code review
            </Link>{' '}
            will run for all pull requests in this organization. Premium requests consumed will be billed as paid usage
            directly to your organization.
          </Text>
          {showPruWarning && (
            <Text sx={{display: 'flex', alignItems: 'flex-start', mt: 2, color: 'fg.muted'}}>
              <Box sx={{flexShrink: 0, mr: 2, mt: '2px'}}>
                <InfoIcon size={16} />
              </Box>
              <span>
                <Link
                  href="https://docs.github.com/en/copilot/how-tos/manage-and-track-spending/manage-request-allowances#setting-a-policy-for-paid-usage"
                  inline
                >
                  Premium request paid usage
                </Link>{' '}
                needs to be enabled by your enterprise in order to use this feature.
              </span>
            </Text>
          )}
        </FormControl.Caption>
      </FormControl>
    </Box>
  )
}

export default function SparkPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const policy = payload.spark
  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: policy.options,
    controls: policy.manages,
    defaultOption: {
      value: 'NA',
      id: 'unconfigured',
      title: 'Unconfigured',
    },
  })

  const disabled = !policy.configurable

  if (!policy.visible) {
    return null
  }

  return (
    <>
      <Box sx={{display: 'flex', flexDirection: 'column', width: '100%'}}>
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: selected?.value === 'enabled' ? 'start' : 'center',
          }}
        >
          <div data-testid={`cfb-policies-${policy.manages}-feature`} style={{maxWidth: 750}}>
            <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
            {policy.description}
            <br />
            {policy.helpurl && policy.helptext && (
              <Link href={policy.helpurl} inline>
                {policy.helptext}
              </Link>
            )}{' '}
            Use of previews is subject to{' '}
            <Link href="https://docs.github.com/en/site-policy/github-terms/github-pre-release-license-terms" inline>
              {"GitHub's pre-release terms"}
            </Link>
            .{selected?.value === 'enabled' && <SparkForceOrgPolicy payload={payload} />}
          </div>
          {disabled ? (
            <span data-testid={`cfb-policies-${policy.manages}-feature-locked`}>
              <ShieldLockIcon /> {selected?.title ?? 'Disabled'}
            </span>
          ) : (
            <ActionMenuButton
              title={selected?.title ?? 'Disabled'}
              options={options}
              onSelect={onSelect}
              disabled={disabled}
              loading={loading}
              data-testid={`cfb-policies-${policy.manages}-control`}
            />
          )}
        </Box>
      </Box>
    </>
  )
}

