import {AvatarStack} from '@primer/react'
import {Box, Text} from '@primer/styled-react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ownerAvatarPath} from '@github-ui/paths'
import {pluralize} from '../helpers/text'
import type {MemberRequestInfo} from '../types'

type MemberRequestsComponentProps = {
  memberRequests: MemberRequestInfo
  entityType?: 'admin' | 'member'
}

export function MemberRequestsComponent({memberRequests, entityType = 'member'}: MemberRequestsComponentProps) {
  const {should_render, requests_count, requesting_users, feature_name} = memberRequests

  if (!should_render || requests_count === 0) {
    return null
  }

  const formatCountText = (count: number, type: string) => {
    return (
      <>
        <strong>{pluralize(count, type, 's')}</strong> requested {feature_name}
      </>
    )
  }

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        mb: 0,
        mt: 0,
        pl: 0,
        backgroundColor: 'canvas.default',
        position: 'relative',
        zIndex: 2,
      }}
    >
      {requesting_users.length > 0 && (
        <Box sx={{mr: 2}}>
          <AvatarStack disableExpand>
            {requesting_users.slice(0, 5).map(user => (
              <GitHubAvatar
                key={user.id}
                src={ownerAvatarPath({owner: user.display_login})}
                alt={user.display_login}
                size={20}
              />
            ))}
          </AvatarStack>
        </Box>
      )}
      <Text as="span" sx={{color: 'fg.muted', fontSize: 0}}>
        {formatCountText(requests_count, entityType)}
      </Text>
    </Box>
  )
}

try{ MemberRequestsComponent.displayName ||= 'MemberRequestsComponent' } catch {}