import React, {useState} from 'react'
import {Link, ToggleSwitch} from '@primer/react'
import {ActionMenuButton, type ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import {enterpriseBudgetsUrl, orgBudgetsUrl, useOverageUpdate} from '../hooks/use-overages'
import {Divider} from '../traditional/components/Ui'
import type {CopilotForBusinessPoliciesPayload} from '../types'
import {ShieldLockIcon} from '@primer/octicons-react'

interface Props {
  enterprise_name: string | null
  org_name: string
  payload: CopilotForBusinessPoliciesPayload
  enterprise_slug: string | null
}

interface PremiumRequestType {
  id: string
  title: string
  description: string
  featureEnabled: boolean
  policyName: 'copilot_premium_request' | 'spark' | 'coding_agent_premium_request'
  type: 'sku' | 'product'
}

export default function OveragesPolicy({enterprise_name, org_name, payload, enterprise_slug}: Props) {
  const premiumRequestTypes: PremiumRequestType[] = [
    {
      id: 'copilot-premium-request',
      title: 'Opt in to Copilot premium request paid usage',
      description: 'Enables billing for Copilot premium requests',
      featureEnabled: true,
      policyName: 'copilot_premium_request',
      type: 'sku',
    },
    {
      id: 'spark-premium-request',
      title: 'Opt in to Spark premium request paid usage',
      description: 'Enables billing for Spark premium requests',
      featureEnabled: payload.spark.visible === true,
      policyName: 'spark',
      type: 'product',
    },
    {
      id: 'copilot-coding-agent-request',
      title: 'Opt in to Copilot coding agent request paid usage',
      description: 'Enables billing for Copilot coding agent premium requests',
      featureEnabled: true,
      policyName: 'coding_agent_premium_request',
      type: 'sku',
    },
  ]
  const actionMenuTitles = {
    enable: 'Enabled',
    selected: 'Enabled for selected products',
    disable: 'Disabled',
  }
  const enabledPremiumRequestTypes = premiumRequestTypes.filter(type => type.featureEnabled)
  const determineOverageState = (): string => {
    const toggledCount = enabledPremiumRequestTypes.filter(
      type => payload.overages[type.policyName]?.value === true,
    ).length

    if (toggledCount === 0) return 'disable'
    if (toggledCount === enabledPremiumRequestTypes.length) return 'enable'
    return 'selected'
  }
  const entityName = enterprise_name ? 'enterprise' : 'organization'
  const [enabled, setEnabled] = useState<string>(() => determineOverageState())

  const options: ActionMenuButtonOption[] = [
    {
      id: 'enable',
      value: 'enable',
      title: actionMenuTitles.enable,
      description: `Your ${entityName} will be billed for premium request paid usage.`,
      selected: enabled === 'enable',
    },
    {
      id: 'selected',
      value: 'selected',
      title: actionMenuTitles.selected,
      description: `Your ${entityName} will only be billed for premium request paid usage from the selected products.`,
      selected: enabled === 'selected',
    },
    {
      id: 'disable',
      value: 'disable',
      title: actionMenuTitles.disable,
      description: `Your ${entityName} will not be charged for premium request overages.`,
      selected: enabled === 'disable',
    },
  ]

  const linkToBudgets = enterprise_slug ? enterpriseBudgetsUrl(enterprise_slug) : orgBudgetsUrl(org_name)
  const isStandaloneOrg = !enterprise_name
  const isEnterpriseOwnedOrg = enterprise_name && org_name
  const slug = isStandaloneOrg ? org_name : enterprise_slug ?? ''

  // Call the hook at the top level
  const {updateOveragePolicy, loading, error} = useOverageUpdate({
    slug,
    isOrg: isStandaloneOrg,
  })

  const handleSelect = (option: ActionMenuButtonOption) => {
    const isEnabled = option.value === 'enable' || option.value === 'selected'
    for (const type of enabledPremiumRequestTypes) {
      updateOveragePolicy(type.policyName, type.type, isEnabled)
    }
    setEnabled(option.value as string)
  }

  const handleToggle = (premiumRequestType: PremiumRequestType, toggleEnabled: boolean) => {
    updateOveragePolicy(premiumRequestType.policyName, premiumRequestType.type, toggleEnabled)
  }

  return (
    <div style={{display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', width: '100%'}}>
      <div data-testid={`cfb-policies-overages-feature`} style={{maxWidth: 600}}>
        <PreviewFeatureHeading title="Premium request paid usage" beta={false} />
        When enabled, your {entityName} will be charged for premium requests that exceed your included usage.{' '}
        {isEnterpriseOwnedOrg && 'This setting is controlled at the enterprise level.'}
        <br />
        <Link href={linkToBudgets} inline>
          Set a budget to control your maximum spend.
        </Link>
        <br />
      </div>
      {isEnterpriseOwnedOrg ? (
        <span data-testid={`cfb-policies-overages-feature-locked`}>
          <ShieldLockIcon /> {actionMenuTitles[enabled as keyof typeof actionMenuTitles] ?? 'Policy Status Unavailable'}
        </span>
      ) : (
        <ActionMenuButton
          title={actionMenuTitles[enabled as keyof typeof actionMenuTitles]}
          options={options}
          onSelect={handleSelect}
          disabled={false}
          loading={loading}
          data-testid={`cfb-policies-overages-control`}
        />
      )}

      {error && <div style={{color: 'red'}}>{error}</div>}

      {enabled === 'selected' && (
        <>
          <Divider />
          {enabledPremiumRequestTypes.map((type, index, filtered) => (
            <React.Fragment key={type.id}>
              <div style={{marginLeft: 40, width: '700px'}} id={type.id} data-testid={`cfb-policies-${type.id}`}>
                <PreviewFeatureHeading title={type.title} beta={false} />
                {type.description}
              </div>

              <ToggleSwitch
                size="small"
                onChange={newValue => handleToggle(type, newValue)}
                defaultChecked={payload.overages[type.policyName]?.value === true}
                data-testid={`cfb-policies-${type.id}-switch`}
                aria-labelledby={type.id}
              />

              {index < filtered.length - 1 && (
                <div style={{marginLeft: 40, width: '100%'}}>
                  <Divider />
                </div>
              )}
            </React.Fragment>
          ))}
        </>
      )}
    </div>
  )
}

try{ OveragesPolicy.displayName ||= 'OveragesPolicy' } catch {}